from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[3];D=Path(__file__).parent;W=D.parent;O=D/'nana_base_hover_relations01'
sha=lambda b:hashlib.sha256(b).hexdigest();rel=lambda p:p.relative_to(ROOT).as_posix()
r=json.loads((O/'report.json').read_text('utf8'))
assert sha((O/'report.json').read_bytes())=='6f1fbfdef566fff22ddc96e6bb73b1a0c0e704eef202c2e09d94fc420f389533'
viewed=[W/'root_nana_hover'/rg/f'comparison_{i}.png'for rg in ['registered01','registered02']for i in [1,2]]
viewed += [O/f'{form}_{n}_jet_contacts.png'for n in [221,223,225,227]for form in ['base_legs','fourth']]
v={'scope':'8개 초기 등록 그림/원점별 중립색 추진효과의 정적 열람. 아트 최종수용/실기 아님.','report':rel(O/'report.json'),'report_sha256':sha((O/'report.json').read_bytes()),'actually_viewed':[{'path':rel(p),'sha256':sha(p.read_bytes())}for p in viewed],'observations':['221/223 새 머릿결·커프·소매와 다리 명암이 대기와 이어진다. 이 정적판에서 추가 확정 팔꿈치/손목 단절은 찾지 못했다. 손 모양은 달라졌고 원손 좌표 exact로 판단하지 않는다.','221 양폼 최저발25→27,223은25→26이다. 발끝과 위쪽 손/눈의 이동량은 같지 않으므로 눈만 맞추는 전신이동이나 전신축소를 권고하지 않는다. 원jet3위상 모두 신발 주변에 겹치지만 정적 overlap 수 자체는 접점 품질의 통과기준이 아니다.','225/227은 상체와 다리가 함께 왼쪽/위쪽으로 이동했다. 225 최저발26→23,227은25→22. 225 눈은base(-7,-15)/Fourth(-7,-16),227은양폼(-7,-15)라 (+2~3,+3)의 강체등록 시험 뒤 폼별 눈 한셀 차이와 두 발/jet 위치를 따로 판단할 수 있다. 이 숫자는 최종정합 승인값이 아니다.','225/227 고정등록 상태의 jet초기위상은 발끝과 옆으로 치우쳐 보인다. 새 발의 실루엣을 원몸체로 덮거나 원효과를 옮기지 말고 먼저 새몸 강체등록 결과를 대조하는 것이 타당하다.','새 원화의 그림이 단일연결이라는 사실과 손이 사랑이를 쥐는 의미/원발사점과의 연결은 별개이다. 사격5는 아직 새후보가 없으므로 본 검토의 수용범위가 아니다.'],'code_conclusions':['원기본형의 hover 진입은 player_check_air_move의 unlocked/air_action0/X 검사 뒤, player+0xA7 bit8 및 새jump입력을 필요로 한다. 기본 비교명 base_legs(mask8)가 맞으며 noarmor mask0를 실제 호버의 완성몸체로 쓰지 않는다.','PL00의5층은머리,6몸통,7팔,8다리 아머이다. 5층이 하체인 현재 Ultimate217..230의 특수제작 구조와 혼동하지 않는다. 사격짝에서 머리5와다리8은 모두exact,몸통6/팔7은 대부분차이로 직접 조사했다.','원US PL00/PL02와 RN39 PL00/PL02의 jet bank12 15frame/30part는 flags/tile/x/y 동일. 기록offset은PL00기준PL02가1464B뒤다. 실제소비전체타일504..509는4ARC 모두exact이며 전체static entry까지 USexact라는 뜻은 아니다.','원visual0x21은world원점/방향을플레이어에서복사한다. 별도위치보정없음. 221/223/225/227/229쌍은jet animation33/34/35/36/32의3위상이다.','원일반탄7단계의static bank1파트와소비타일도4ARCexact. 실제원점222(-27,-9),224(-29,-8),226(-20,-10),228(-17,-10),230(-24,-11),direction1은X만반전. type0추가offset0. 원총구8열 보존만으로 탄환접점을 입증하지 않는다.'],'limits':['코드와테이블의정적읽기/원바이트대조이며 새로운MIPS실행아님.','그림/효과는동일원점의중립청록진단합성. 실제CLUT0x7802 게임색/드로우순서/60Hz캡처가아님.','원화 재양자화/패킹/파일수정/게임조작 미실행.','draft_eye_color는초기넓은색ROI에uint8비교overflow가있어미채택. 최종보고는명시적index14의실제RGB만사용한녹색좌표로재산출했다. 피부색ROI는귀/목을포함할수있어관절확정으로쓰지않는다.']}
p=O/'visual.json';assert not p.exists();p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n','utf8')
tracked=dict(r['inputs'])
for p in [D/'audit_nana_base_hover_relations01.py',Path(__file__),O/'report.json',O/'visual.json']+viewed:tracked[rel(p)]=sha(p.read_bytes())
for path,h in tracked.items():assert sha((ROOT/path).read_bytes())==h,path
p=O/'READER_LOCK.json';assert not p.exists();p.write_text(json.dumps({'inputs':tracked,'count':len(tracked),'source_writes':False,'producer_calls':False},ensure_ascii=False,indent=2)+'\n','utf8')
print(json.dumps({'visual_sha256':sha((O/'visual.json').read_bytes()),'lock_sha256':sha(p.read_bytes()),'input_count':len(tracked)}))
